st_write(setores, file.path(AUX_DIR, "setores_2022.gpkg"), delete_dsn = TRUE)

1. Download

url_locais &lt;- sprintf(
  "https://cdn.tse.jus.br/estatistica/sead/odsele/eleitorado_locais_votacao/eleitorado_local_votacao_%d.zip",
  ano
)
caminho_zip &lt;- file.path(BRUTO_DIR, sprintf("eleitorado_local_votacao_%d.zip", ano))

baixar_com_retry &lt;- function(url, destino, tentativas = 3) {
  if (file.exists(destino)) {
    return(invisible(destino))
  }
  for (tentativa in seq_len(tentativas)) {
    resultado &lt;- tryCatch(
      {
        resp &lt;- request(url) |&gt;
          req_user_agent("dados_eleicoes (CEM/USP)") |&gt;
          req_perform()
        writeBin(resp_body_raw(resp), destino)
        TRUE
      },
      error = function(e) {
        message(sprintf("Tentativa %d/%d falhou: %s", tentativa, tentativas, conditionMessage(e)))
        FALSE
      }
    )
    if (isTRUE(resultado)) break
    if (tentativa &lt; tentativas) Sys.sleep(2^tentativa)
  }
  if (!file.exists(destino)) stop("Não foi possível baixar ", url)
  invisible(destino)
}

baixar_com_retry(url_locais, caminho_zip)

3. Chaves e crosswalk
O arquivo real (confirmado em 28/09/2026, ver CLAUDE.md) traz uma linha por seção por turno (NR_TURNO), não uma linha por seção — então id_secao sozinho não é único; a chave completa da linha é (id_secao, nr_turno). O CD_MUNICIPIO já vem com 5 dígitos e zero à esquerda ("01120"), no mesmo formato do cd_mun_tse do crosswalk depois do str_pad() da etapa 00.

crosswalk &lt;- read_parquet("dados/02_processado/aux/crosswalk_mun_tse_ibge.parquet")

locais_com_chave &lt;- locais_bruto |&gt;
  mutate(
    nr_turno = as.integer(nr_turno),
    id_local_proprio = str_c(
      cd_municipio,
      str_pad(nr_zona, CRESCE_ZONA, pad = "0"),
      str_pad(nr_local_votacao, CRESCE_NUM, pad = "0")
    ),
    id_secao = str_c(
      cd_municipio,
      str_pad(nr_zona, CRESCE_ZONA, pad = "0"),
      str_pad(nr_secao, CRESCE_NUM, pad = "0")
    )
  ) |&gt;
  left_join(crosswalk, by = c("cd_municipio" = "cd_mun_tse"))

n_sem_crosswalk &lt;- sum(is.na(locais_com_chave$cd_mun) & locais_com_chave$sg_uf.x != "ZZ")
if (n_sem_crosswalk &gt; 0) {
  warning(n_sem_crosswalk, " locais sem crosswalk para município IBGE (fora do exterior).")
}


Seções agregadas: resolver o local pela seção principal
DS_TIPO_SECAO_AGREGADA tem três valores (contados no arquivo real de 2022): Principal (944.150 linhas), Agregada (48.326) e Distribuída de ofício (1.236). Só a Agregada tem NR_SECAO_PRINCIPAL de verdade (as outras trazem -1, sentinela de “não se aplica”). Em 952 das 48.326 (~2%) o NR_LOCAL_VOTACAO da própria linha “Agregada” diverge do local da seção principal — resolver pelo NR_SECAO_PRINCIPAL é obrigatório, não um detalhe cosmético. A resolução é feita dentro do mesmo nr_turno, porque a seção principal referenciada é a do mesmo turno.

locais_com_chave &lt;- locais_com_chave |&gt;
  mutate(
    id_secao_principal = if_else(
      nr_secao_principal != "-1",
      str_c(
        cd_municipio,
        str_pad(nr_zona, CRESCE_ZONA, pad = "0"),
        str_pad(nr_secao_principal, CRESCE_NUM, pad = "0")
      ),
      NA_character_
    )
  )

local_por_secao &lt;- locais_com_chave |&gt;
  distinct(id_secao, nr_turno, .keep_all = TRUE) |&gt;
  select(id_secao, nr_turno, id_local_da_secao = id_local_proprio)

locais_com_chave &lt;- locais_com_chave |&gt;
  left_join(
    local_por_secao,
    by = c("id_secao_principal" = "id_secao", "nr_turno" = "nr_turno")
  ) |&gt;
  mutate(id_local = coalesce(id_local_da_secao, id_local_proprio))

n_resolvidas_por_principal &lt;- sum(
  locais_com_chave$id_local != locais_com_chave$id_local_proprio
)
n_resolvidas_por_principal

[1] 1049

6. Municípios com mais de uma zona
Insumo para a camada id_zona_mun (PLAN.md &gt; Pesquisa &gt; Zonas eleitorais): só nesses municípios a geometria da zona precisa ser estimada.

n_zonas_mun &lt;- locais |&gt;
  distinct(cd_mun, nr_zona) |&gt;
  count(cd_mun, name = "n_zonas_mun") |&gt;
  arrange(desc(n_zonas_mun))

write_parquet(n_zonas_mun, file.path(PROCESSADO_DIR, sprintf("n_zonas_mun_%d.parquet", ano)))
head(n_zonas_mun, 10)

2. Validação da coordenada do TSE
Reprova quando a coordenada é nula, (0, 0), (-1, -1) (valor sentinela do TSE para o exterior), cai fora do próprio município, ou é repetida em 3 ou mais locais do mesmo município (provável centróide usado como preenchimento).

valida_coordenada_tse &lt;- function(locais, municipios, buffer_m = BUFFER_MUNICIPIO_M) {
  locais &lt;- locais |&gt;
    mutate(
      coord_nula = is.na(latitude) | is.na(longitude),
      coord_sentinela = !coord_nula & (
        (latitude == 0 & longitude == 0) | (latitude == -1 & longitude == -1)
      )
    )

  candidatos &lt;- locais |&gt; filter(!coord_nula & !coord_sentinela)

  if (nrow(candidatos) &gt; 0) {
    pontos &lt;- st_as_sf(candidatos, coords = c("longitude", "latitude"), crs = 4674, remove = FALSE)

    municipios_buffer &lt;- municipios |&gt;
      st_transform(5880) |&gt;
      st_buffer(buffer_m) |&gt;
      st_transform(4674)

    # st_intersects em modo esparso (uma vez, para todos os pontos de uma vez
    # via árvore espacial) devolve, para cada ponto, os índices dos polígonos
    # que ele toca; "dentro do próprio município" é só checar se o cd_mun do
    # ponto está entre esses candidatos. Evita o loop ponto a ponto (que
    # refiltrava os ~5.570 municípios a cada uma das ~90 mil linhas).
    candidatos_por_ponto &lt;- st_intersects(pontos, municipios_buffer)
    cd_mun_dos_poligonos &lt;- municipios_buffer$cd_mun
    dentro_do_municipio &lt;- vapply(
      seq_along(candidatos_por_ponto),
      \(i) pontos$cd_mun[i] %in% cd_mun_dos_poligonos[candidatos_por_ponto[[i]]],
      logical(1)
    )
    candidatos$coord_fora_municipio &lt;- !dentro_do_municipio
  } else {
    candidatos$coord_fora_municipio &lt;- logical(0)
  }

  candidatos &lt;- candidatos |&gt;
    group_by(cd_mun, latitude, longitude) |&gt;
    mutate(coord_repetida = n() &gt;= 3) |&gt;
    ungroup()

  locais |&gt;
    left_join(
      candidatos |&gt; st_drop_geometry() |&gt; select(id_local, coord_fora_municipio, coord_repetida),
      by = "id_local"
    ) |&gt;
    mutate(
      coord_valida = !coord_nula & !coord_sentinela &
        !coalesce(coord_fora_municipio, TRUE) & !coalesce(coord_repetida, TRUE)
    )
}

locais_validados &lt;- valida_coordenada_tse(locais, municipios)
locais_validados |&gt; count(coord_valida)

3. Cadeia de fallback
MVP (antes de 04/10): outro ano + Hidalgo. Escola e geocodebr entram depois (ver PLAN.md &gt; Etapa 02 &gt; MVP).
Cada passo só age nos locais ainda sem fonte_coord resolvida. Para cada um, calcula a distância entre a coordenada do TSE (mantida à parte em latitude_tse/longitude_tse, mesmo quando reprovada na validação) e a referência do passo: se &lt; LIMIAR_DIST_TSE_REF_M (800 m, regra do geobr::read_polling_places), mantém o TSE — a reprovação era um falso positivo (ex.: coordenada perto da divisa do município) — em vez de trocar por uma referência pior. Só troca de verdade quando o TSE está ausente ou longe.

aplica_fallback &lt;- function(df, referencia, nome_fonte) {
  # referencia: id_local, latitude_ref, longitude_ref
  df |&gt;
    left_join(referencia, by = "id_local") |&gt;
    mutate(
      dist_ref_m = calcula_distancia_m(latitude_tse, longitude_tse, latitude_ref, longitude_ref),
      candidato = is.na(fonte_coord) & !is.na(latitude_ref),
      tse_confirmada = candidato & !is.na(dist_ref_m) & dist_ref_m &lt; LIMIAR_DIST_TSE_REF_M,
      usa_referencia = candidato & !tse_confirmada,
      latitude = case_when(
        tse_confirmada ~ latitude_tse, usa_referencia ~ latitude_ref, TRUE ~ latitude
      ),
      longitude = case_when(
        tse_confirmada ~ longitude_tse, usa_referencia ~ longitude_ref, TRUE ~ longitude
      ),
      fonte_coord = case_when(
        !is.na(fonte_coord) ~ fonte_coord,
        tse_confirmada ~ "tse_confirmado",
        usa_referencia ~ nome_fonte,
        TRUE ~ NA_character_
      )
    ) |&gt;
    select(-latitude_ref, -longitude_ref, -dist_ref_m, -candidato, -tse_confirmada, -usa_referencia)
}

referencia_outro_ano &lt;- function(ano_referencia) {
  caminho &lt;- file.path(GEOMETRIAS_DIR, sprintf("geom_locais_votacao_%d.gpkg", ano_referencia))
  if (!file.exists(caminho)) return(NULL)
  st_read(caminho, quiet = TRUE) |&gt;
    st_drop_geometry() |&gt;
    transmute(id_local, latitude_ref = latitude, longitude_ref = longitude)
}

referencia_hidalgo &lt;- function() {
  caminho &lt;- "dados/01_bruto/aux/geocoded_polling_stations.csv.gz"
  if (!file.exists(caminho)) {
    warning("Painel Hidalgo não encontrado em ", caminho, " — baixar de ",
            "github.com/fdhidalgo/geocode_br_polling_stations (release v0.16).")
    return(NULL)
  }
  # Esquema real do painel (confirmado em 28/09/2026, colunas já em
  # snake_case): cd_localidade_tse (SEM zero à esquerda, ao contrário do
  # CD_MUNICIPIO do TSE), nr_zona, nr_locvot, pred_lat/pred_long (a
  # coordenada geocodificada, independente da do TSE — não usar `lat`/`long`,
  # que já vêm misturadas com a coordenada do TSE de outro ano/snapshot).
  readr::read_csv(caminho, show_col_types = FALSE) |&gt;
    filter(ano == !!ano) |&gt;
    transmute(
      id_local = str_c(
        str_pad(cd_localidade_tse, 5, pad = "0"),
        str_pad(nr_zona, 4, pad = "0"),
        str_pad(nr_locvot, 4, pad = "0")
      ),
      latitude_ref = pred_lat,
      longitude_ref = pred_long
    ) |&gt;
    distinct(id_local, .keep_all = TRUE)
}

locais_final &lt;- locais_validados |&gt;
  mutate(
    latitude_tse = latitude,
    longitude_tse = longitude,
    fonte_coord = if_else(coord_valida, "tse", NA_character_)
  )

ref_outro_ano &lt;- referencia_outro_ano(if (ano == 2026) 2022 else 2018)
if (!is.null(ref_outro_ano)) {
  locais_final &lt;- aplica_fallback(locais_final, ref_outro_ano, sprintf("ano_%d", if (ano == 2026) 2022 else 2018))
}

ref_hidalgo &lt;- referencia_hidalgo()
if (!is.null(ref_hidalgo)) {
  locais_final &lt;- aplica_fallback(locais_final, ref_hidalgo, "hidalgo")
}

# Último degrau (PLAN.md &gt; Etapa 02, passo 5): centróide do município, com
# flag. Só sobra `sem_coord` de verdade para quem nem isso tem — o exterior
# (`cd_mun` NA, sem crosswalk) e municípios sem geometria. Sem este passo, os
# locais não resolvidos ficavam com a coordenada INVÁLIDA original do TSE
# (ex.: o sentinela -1,-1), publicada como se fosse um ponto de verdade —
# bug real, achado inspecionando os bounds da saída (`longitude` batendo
# exatamente em -1.0).
centro_municipios &lt;- st_centroid(municipios) |&gt; st_transform(4674)

Warning: st_centroid assumes attributes are constant over geometries

coords_centro &lt;- st_coordinates(centro_municipios)
centroides &lt;- centro_municipios |&gt;
  st_drop_geometry() |&gt;
  transmute(cd_mun, latitude_centroide = coords_centro[, 2], longitude_centroide = coords_centro[, 1])

locais_final &lt;- locais_final |&gt;
  left_join(centroides, by = "cd_mun") |&gt;
  mutate(
    usa_centroide = is.na(fonte_coord) & !is.na(latitude_centroide),
    latitude = if_else(usa_centroide, latitude_centroide, latitude),
    longitude = if_else(usa_centroide, longitude_centroide, longitude),
    fonte_coord = case_when(
      !is.na(fonte_coord) ~ fonte_coord,
      usa_centroide ~ "centroide_municipio",
      TRUE ~ NA_character_
    )
  ) |&gt;
  select(-latitude_centroide, -longitude_centroide, -usa_centroide)

locais_final &lt;- locais_final |&gt;
  mutate(
    fonte_coord = coalesce(fonte_coord, "sem_coord"),
    flag_sem_coord = fonte_coord %in% c("sem_coord", "centroide_municipio"),
    # sem_coord de verdade não tem coordenada nenhuma para publicar (ex.: o
    # exterior, sem cd_mun/centróide) — vira NA em vez de carregar o
    # sentinela do TSE adiante.
    latitude = if_else(fonte_coord == "sem_coord", NA_real_, latitude),
    longitude = if_else(fonte_coord == "sem_coord", NA_real_, longitude)
  ) |&gt;
  select(-latitude_tse, -longitude_tse)

locais_final |&gt; count(fonte_coord) |&gt; mutate(pc = round(100 * n / sum(n), 2))
